body:
start
:Parse ingest options;
if (Highway mode?) then (yes)
 if (Incompatible arguments?) then (yes)
  :Return 2;
  stop
 endif
 :ingest_highway;
 :Return nested result;
 stop
endif
:Validate claims/entities files and source selection;
if (Invalid selection?) then (yes)
 :Return 2 or missing source 1;
 stop
endif
:Load recipes and source order;
if (All arguments are source names, or no selected files?) then (yes)
 :ingest_every with dependency closure / recipe order;
 :Return nested result;
 stop
endif
:Enumerate files; resolve recipe and source;
:Report uncovered files; order by trust and reference dependency;
if (Plan only?) then (yes)
 :Print mapping; return 0;
 stop
endif
:Open contexts; initialize source-wide fold;
if (Loading?) then (yes)
 :Check files_recorded using stored OS metadata;
endif
while (More file batches?) is (yes)
 :Respect dependency-depth barrier and batch byte budget;
 if (Oversized streamable file?) then (yes)
  :Two-pass stretch path: calculate trunk then record stretches;
  :Check known trunk / missing descendants; collect source fold;
 else (ordinary batch)
  :Decompose unskipped unknown files with OpenMP tasks;
  :Recompose bytes and compare; curated recipe skips byte comparison;
  :Accumulate mismatch count / show claims or entities if requested;
  if (Loading?) then (yes)
   :Mark staging; ingest_known; fold_events;
   :Wait prior loader before writing next batch;
   if (Windows or final batch?) then (yes)
    :load synchronously;
   else (non-Windows with next batch)
    :Fork loader; parent proceeds to next decomposition;
   endif
  endif
 endif
 if (Loader / pipe / fork reports failure?) then (yes)
  :Return 1; prior commits may remain;
  stop
 endif
 :Free batch events and reset working node table;
endwhile (no)
:Wait final loader; report recomposition and incomplete parts;
if (No-load / claims / entities?) then (yes)
 :Return mismatch ? 1 : 0;
 stop
endif
if (No mismatch and fold nonempty?) then (yes)
 :standings_write once per source claim series;
endif
:Report conflicting records / claims without provenance;
if (One whole source, no mismatch, source record exists?) then (yes)
 :Compose and load source trunk; retain witness ID / trust / lineage;
else (no)
 :Report absence of source witness trunk;
endif
if (No mismatch?) then (yes)
 :merge staged state;
 if (Source witness trunk available?) then (yes)
  :INSERT witness if absent;
 endif
endif
:Return mismatch ? 1 : 0;
stop
legend
load / standings_write / source_trunk / merge remain nested operations.
Failures in those operations return 1. This is not one atomic source transaction.
Metadata precheck conflicts with Wiki 11.2 trunk-first deduplication.
endlegend

start
:Parse connection, firmware, user, session, seed, read-only flag;
if (Prompt absent?) then (yes)
 :Return 2;
 stop
endif
:Load firmware / tier0; create composition contexts and database reader;
:Compose exact prompt, user and session handle;
:Read prior turns; order by recorded position; collect discourse;
if (Not --read?) then (yes)
 :load prompt content under user witness;
 if (load fails?) then (yes)
  :Return 1;
  stop
 endif
endif
:resolve_roles; initialize occurrences and trajectory;
:COUPLE occurrences, whole prompt, discourse;
:ORIENT nearest curves; determine remaining obligations;
:orient joint bindings and ambiguity; choose route centres;
:SCAN bounded centres; form chain answers;
if (Ambiguous joint orientation?) then (yes)
 :Set ambiguous disposition and emission budget to zero;
else (no)
 :Use firmware emission budget;
endif
while (Emission steps remain?) is (yes)
 :PROPOSE observed continuations and chain answers;
 if (No proposals or proposals ground no open obligation?) then (yes)
  :Set unresolved disposition;
  break
 endif
 :STEER / SELECT by grounds, continuity, confidence, hub;
 :Optional seeded selection within firmware top_within;
 :REALIZE selected entity to text;
 :Append selected ID to bounded emitted/trajectory arrays;
 :Clear supported obligations; COUPLE emitted constituent;
 if (Non-follow act reaches firmware sufficiency?) then (yes)
  :Set complete / remaining-within-bound disposition;
  break
 endif
endwhile (no)
:Report text and disposition; emission-budget status if spent;
if (Not --read and nonempty output?) then (yes)
 :Compose response and turn;
 :Create [session, turn] and [response, prompt] claim events;
 :load under user and Laplace witnesses;
 if (load fails?) then (yes)
  :Return 1;
  stop
 endif
else (no)
 :Print read-only or nothing-emitted witness disposition;
endif
:Report round trips; free field / bindings / reader / connection;
:Return 0;
stop
legend
Source bounds include MAXOCC 256, emitted 512, trajectory 4096.
Named stages do not prove universal ISA conformance.
Prompt admission precedes response; no whole-turn rollback established.
Bookkeeping claim events must be reconciled with conflict C1.
endlegend

start
:Parse --write / --tsv / --voices / --files;
:Map tier0; connect; create reader;
:SELECT witness IDs and trust;
:Calculate source rank; sort witnesses by rank and ID;
if (TSV requested and open fails?) then (yes)
 :Return 1;
 stop
endif
while (More witness trunks?) is (yes)
 :walk_down; propagate occurrence counts; tally_under;
 while (More positive-game claim tallies?) is (yes)
  :Initialize stock standing if absent;
  :lp_attest_series(trust, games, mean score, floor);
  :Accumulate matches / print optional TSV;
 endwhile (no)
 :Optionally output voice and file tallies;
 :Free witness DAG and tallies;
endwhile (no)
:Read existing consensus in sets of up to 50000;
:Compare rating / deviation / volatility bitwise and match count;
:Count same, different and missing BEFORE writing;
if (--write and replayed set nonempty?) then (yes)
 :BEGIN; create temporary replayed table;
 :Binary COPY replayed standings;
 :UPDATE existing consensus; INSERT missing consensus;
 :COMMIT;
endif
:Print comparison; close TSV, maps, reader and connection;
:Return 1 if pre-write different or missing, otherwise 0;
stop
legend
--write is a mutation; default compares only.
A return of 1 after --write can report the pre-write mismatch.
This function does not delete extra consensus rows outside the replayed set.
endlegend

start
:Parse witness selectors, --trunk and --except;
if (No selectors and not --except?) then (yes)
 :Return 2;
 stop
endif
:Map tier0; connect worker connections;
:Parse trunk IDs or decompose source names;
if (Invalid explicit ID?) then (yes)
 :Return 2;
 stop
endif
:Read witnesses; compare trunk ID or first source-record constituent;
:Apply --except inversion to selected set;
if (No matching witnesses?) then (yes)
 :Return 1;
 stop
endif
:Collect distinct claims under selected source trunks;
:DELETE selected witness rows;
:sweep seeded with removed trunks;
:standings_replay on touched claims;
:Read remaining testimony in sets; order by claim / source rank / trunk ID;
:Play surviving positive-game witness series;
:Compare and write rebuilt standings through stands_compare;
:DELETE consensus for touched claims with no surviving witness;
:Close connections and free touched set; return 0;
stop
legend
Destructive operation; diagram generation does not execute it.
Witness deletion, sweep and replay are not enclosed in one transaction here.
Shared content eligibility is decided by sweep's reference counts and roots.
endlegend

start
:Parse connection / workers / --dry; reject extra args with return 2;
:Map tier0 and open connections;
:Discover populated entity / physicality partitions;
:Read paths above tier0 in parallel; count holders by child ID;
:Mark witness trunks and lineages as roots;
if (Standalone sweep?) then (yes)
 :Keep non-curated file roots;
 :Select entities with no holder and no root;
else (forget supplies seed)
 :Select seed entities that are not roots;
endif
while (Current removal set nonempty?) is (yes)
 :Read selected paths; decrement child holder counts;
 :Queue newly unheld non-root entities;
 if (Not dry?) then (yes)
  :DELETE consensus for selected IDs;
  :DELETE selected physicality rows by partition;
  :DELETE selected entity rows by partition;
 endif
 :Report level; advance removal set;
endwhile (no)
:Free count maps; report total;
:Close connections; return 0;
stop
legend
--dry calculates cascade without issuing the deletion statements.
This source does not wrap the whole cascade in a single transaction.
The tier0 paths are excluded from the scanned entity set.
endlegend

start
if (Which public operation?) then (lp_id_codepoint)
 :Encode codepoint with lp_utf8_put;
 :lp_hash16 UTF-8 bytes;
 :Return 128-bit ID;
 stop
elseif (Operation?) then (lp_id_compose)
 if (Exactly one child?) then (yes)
  :Copy child ID;
 else (zero or many)
  :lp_hash16 ordered contiguous child IDs;
 endif
 :Return ID;
 stop
else (lp_ref_compose)
 if (Exactly one child?) then (yes)
  :Return entire child reference;
  stop
 endif
 :Initialize zero reference and selected tier;
 if (No children?) then (yes)
  :Return zero reference;
  stop
 endif
 if (At most 64 children?) then (yes)
  :Gather IDs; sum each coordinate; lp_hash16;
 else (more)
  :Stream groups of up to 64 ordered IDs into BLAKE3;
  :Accumulate child coordinates; finalize first 16 bytes;
 endif
 :lp_coord_mean from accumulated coordinates;
 :Return identity, coordinate and tier;
 stop
endif
legend
No recipe, tier, source, coordinate or domain prefix is hashed here.
Empty lp_id_compose hashes empty bytes; empty lp_ref_compose returns zeros.
These entry points therefore do not have identical empty-input behavior.
One-child reference composition preserves the child's tier too.
endlegend

start
:lp_attest_series(rating, trust, games, mean score, floor);
if (Trust zero or games zero?) then (yes)
 :Return unchanged;
 stop
endif
:Clamp score to [0,1];
if (Negative trust?) then (yes)
 :Flip score; use absolute trust;
endif
:Clamp trust at 1;
:Effective score = 0.5 + trust * (score - 0.5);
:Convert prior rating and deviation to scaled coordinates;
:Bracket posterior mode between prior and effective-score logit,
also bounded by games * prior_variance;
while (Bisection iterations below 2000?) is (yes)
 :Compute midpoint;
 if (Midpoint equals or exceeds a bracket endpoint?) then (yes)
  break
 endif
 :Evaluate posterior slope;
 if (Slope positive?) then (yes)
  :Move lower endpoint;
 else (no)
  :Move upper endpoint;
 endif
endwhile (no)
:Calculate mode and posterior deviation;
:Apply lp_series_floor(trust, floor);
:Cap new deviation at prior deviation;
:Write rating and deviation; leave volatility unchanged;
stop
legend
This is lp_attest_series, not the separate lp_attest scalar matchup.
lp_attest still converts trust to opponent deviation.
Witness-dependence grouping is not performed inside this solver.
The diagram does not establish validity for NaN or invalid prior states.
endlegend

start
:Select host manifest; parse install / deploy / check / select;
if (Select-only or absent manifest?) then (yes)
 :Return selected path or no-declaration result;
 stop
endif
:Validate host, paths, identities, allocation and required inputs;
if (Check-only?) then (yes)
 :Return validated-input result;
 stop
endif
:Require root for install and non-root for recurring deploy;
:Acquire host lock;
if (Install?) then (yes)
 :prepare installation;
else (deploy)
 :Compare installed declaration; require installed unit and restart watcher;
endif
:Create receipt directory; package selected release;
:Validate release is a non-symlink under releases;
:Snapshot prior link / unit / environment / service states;
if (Install?) then (yes)
 :peer_check and candidate probe BEFORE service changes;
endif
:Enter activation recovery boundary;
if (Install?) then (yes)
 :Write unit and environment; verify unit; daemon-reload;
 :Stop previously active legacy service;
endif
:Switch current release link;
if (Install?) then (yes)
 :Enable / start / restart modular service;
else (deploy)
 :Touch restart signal;
endif
:Poll for active service with a new InvocationID;
:Check unit contents; run deployment.py verify into runtime receipt;
if (Install and legacy service was active?) then (yes)
 :Disable legacy service;
endif
if (Activation or verification raises?) then (yes)
 :Restore previous release link or remove newly created link;
 if (Install?) then (yes)
  :Restore unit/environment; daemon-reload;
  :Restore old active service and legacy service where applicable;
 else (previous release exists)
  :Touch restart signal for prior release;
 endif
 :Re-raise original failure unless recovery itself raises;
 stop
endif
if (Install?) then (yes)
 :Install restart watcher; optionally install operator client;
endif
:Write acceptance.json referencing runtime.json;
stop
legend
Candidate probe is before the recovery try block.
Restart-watcher/client setup occurs after activate returns;
failures there are outside activate's rollback boundary.
No installation or service operation was run for this atlas.
endlegend

start

:Parse UCD root and output path;
if (Unexpected arguments?) then (yes)
 :Return 2;
 stop
endif
:load_ucd; load_allkeys; build_keys;
:Sort every codepoint by keycmp; construct rank array;
:Generate fixed-population Super-Fibonacci points;
:Sort points by Hilbert key;
while (More codepoints?) is (yes)
 :Select Hilbert-ordered point at codepoint rank;
 :Round four coordinates to fixed integer grid;
 while (Squared norm exceeds 2^106?) is (yes)
  :Move largest absolute coordinate one integer unit inward;
 endwhile (no)
 :Hash codepoint ID; store coordinate, Hilbert value and rank;
endwhile (no)
:Open output directly; write all records;
if (Open or record write fails?) then (yes)
 :Return 1; partial output may remain;
 stop
endif
:Close; hash record table and three-byte codepoint order;
:Print fingerprints and record count; return 0;
stop

start

:Parse UCD root and flags output path;
if (Unexpected arguments?) then (yes)
 :Return 2;
 stop
endif
:Read property aliases and enumerated value aliases;
:Assign one bit per binary property, then widths for enumerated values;
if (Total width exceeds 256?) then (yes)
 :Return 1;
 stop
endif
:Allocate zeroed 32-byte records and coverage bitmap;
while (More XML lines?) is (yes)
 :Accept char, reserved, noncharacter and surrogate elements;
 :Read property values and codepoint range;
 :Count unknown values; set recognized property bits;
 if (Valid codepoint range?) then (yes)
  :Copy record across range; update coverage;
 endif
endwhile (no)
:Count enumerated values across every record;
:Open flags output directly and write records;
if (Open or record write fails?) then (yes)
 :Return 1;
 stop
endif
:Close records; open layout output;
if (Layout open fails?) then (yes)
 :Return 1; records already written;
 stop
endif
:Write bit layout; close; hash record bytes;
:Report unknown/unseen properties, coverage and fingerprint; return 0;
stop

start

:Parse output path and fingerprint mode;
if (Unexpected arguments?) then (yes)
 :Return 2;
 stop
endif
if (Fingerprint mode?) then (yes)
 :Map existing highway;
 if (Map fails?) then (yes)
  :Return 1;
 else (no)
  :Print existing fingerprint; return 0;
 endif
 stop
endif
:Initialize contexts; disable reading highway being built; load recipes;
while (More sources declaring highway data?) is (yes)
 if (Source root found?) then (yes)
  if (Broken recipes?) then (yes)
   :Return 2;
   stop
  endif
  :Enumerate files; highway_file gathers types, keys, aliases and mappings;
 else (no)
  :Report omitted source;
 endif
endwhile (no)
:Resolve aliases until no key is added;
:freeze slots using manifest; number lists;
:Resolve edges to slots; omit unresolved mappings; sort and deduplicate;
if (No type records?) then (yes)
 :Return 1; existing highway output unchanged;
 stop
endif
:Construct records; write fresh binary;
if (Open, record write or swap fails?) then (yes)
 :Return 1;
 stop
endif
:Binary output replaced;
:Open fresh layout; read and validate manifest banks;
if (Open/bank validation/layout swap fails?) then (yes)
 :Return 1; binary replacement remains;
 stop
endif
:Write and swap keys sidecar;
if (Open or swap fails?) then (yes)
 :Return 1; earlier replacements remain;
 stop
endif
:Write type node compositions and slot IDs; swap nodes sidecar;
if (Open or swap fails?) then (yes)
 :Return 1; earlier replacements remain;
 stop
endif
:Report omitted mappings/keys, counts and binary fingerprint; return 0;
stop

start

:Parse options; load hop firmware and default fan/confidence;
if (Argument count is neither one nor three?) then (yes)
 :Return 2;
 stop
endif
:Map tier0; create text context; connect for reads;
if (Whole entity request?) then (yes)
 :Resolve entity; claims_of;
else (pattern)
 :Resolve subject/predicate/object, leaving question marks open;
 if (All parts open?) then (yes)
  :Return 2;
  stop
 endif
 :claims_like;
endif
:Apply refused and weighed; retrieve witness positions;
:Order pattern results by witness position when configured;
:Decode and print at most limit claims;
if (Pattern request?) then (yes)
 :Cleanup; return 0;
 stop
endif
:Query non-claim containers of whole entity;
if (Query fails?) then (yes)
 :Return 1; claims may already have been printed;
 stop
endif
:Print observed container counts by tier separately from attested claims;
:Cleanup; return 0;
stop

start

:Parse source word, source language, target languages and options;
:Load translate firmware;
if (Missing arguments or missing up/language route?) then (yes)
 :Return 2;
 stop
endif
:Map tier0; open read connection and reader; resolve relation IDs;
:Read first upward claims in witness order;
while (More upward steps and frontier nonempty?) is (yes)
 :open_each for entire frontier;
 if (Last upward step?) then (yes)
  :Retain first concept and standing per origin;
 else (no)
  :Advance claimed targets;
  :For uncarried steps, expand constituents;
  :Exclude original word unless composition contains only that word;
 endif
endwhile (no)
:Resolve synset languages; choose distinct concepts in source language up to limit;
:Read optional gloss and downward synsets in batches;
:Keep requested target languages, at most 64;
while (More downward steps and frontier nonempty?) is (yes)
 :Read inverse relation for whole frontier;
 if (Uncarried step above final word step?) then (yes)
  :Fall back to containing entities;
 endif
endwhile (no)
:Print concept standing, gloss and at most eight unique words per target;
:Print no-concept / nothing-attested labels where applicable;
:Cleanup; return 0;
stop

start

:Parse search options;
if (Missing origin or batch below one?) then (yes)
 :Return 2;
 stop
endif
:Load firmware; resolve origin, optional goal and weights;
:Open reads; seed forward frontier;
if (Goal supplied?) then (yes)
 :Seed backward frontier; best = infinity;
 while (Open costs can improve best and a frontier is available?) is (yes)
  :Expand side with lower open cost, bounded by half hop budget;
  if (Expansion empty?) then (yes)
   break
  endif
  :Compare meetings with opposite frontier; exclude hubs;
  :Keep cheaper meeting within total hop budget;
 endwhile (no)
 if (No meeting found?) then (yes)
  :Report no chain; cleanup; return 1;
  stop
 endif
 :Reconstruct forward chain and reversed backward chain; print;
else (nearest)
 while (Fewer than limit known or open frontier may improve top results?) is (yes)
  :expand forward frontier;
  if (Expansion empty?) then (yes)
   break
  endif
  :Collect closed entities except origin;
 endwhile (no)
 :Sort by cost; reconstruct and print up to limit chains;
endif
:Report expansion statistics; cleanup; return 0;
stop

start

:Report available and active CPU dispatch;
:Time codepoint and composition identity kernels;
:Time ID geometry conversion, EWKB encoding and fixed-coordinate kernels;
:Time scalar continuation scan;
if (AVX2 supported?) then (yes)
 :Time AVX2 scan and later distance kernels;
endif
if (AVX512 supported?) then (yes)
 :Time AVX512 scan;
endif
:Time scalar distance, Frechet, DTW, EDR and outlier kernels;
if (Tier0 can be mapped?) then (yes)
 :Time text decomposition and codepoint lookup;
else (no)
 :Print text measurement skipped;
endif
:Time frontier reach/drain;
:Time scalar attestation and trust-bounded series;
:Return 0;
stop

start
if (Build provides laplace_model target?) then (no)
 :Compile model_none.c handler;
 :Print MKL/OpenMP requirement; return 1;
 stop
else (yes)
 :Compile model.c handler;
endif
if (No model directory?) then (yes)
 :Return 2;
 stop
endif
:Parse layer count, z threshold, cap and sample words;
if (MKL reproducible mode refused?) then (yes)
 :Return 1;
 stop
endif
:Map tier0; parse model config and vocabulary;
:Load model.safetensors embedding, unembedding and final norm;
:Fold norm gain into unembedding;
:Measure normalized embedding similarity and direct output signatures;
while (More selected layers?) is (yes)
 :Normalize original embeddings using layer input norm;
 :Project Q, K and V;
 while (More attention heads?) is (yes)
  :Measure QK row signatures;
  :Measure low-rank OV row signatures;
 endwhile (no)
 :Transpose down-projection directions;
 :Measure FFN neuron-to-token output signatures;
 :Report layer statistics;
endwhile (no)
:Report timing and FLOPs; return 0;
stop

start

:Parse prompt, firmware and optional seed;
if (Prompt absent?) then (yes)
 :Return 2;
 stop
endif
:Select seed; load firmware; decompose prompt and constituents;
:Open read connection and reader;
:laplace_forward retrieves observed segments, run counts and continuations;
if (Query fails?) then (yes)
 :Return 1;
 stop
endif
:Print bounded segment preview; distinguish hubs from counted runs;
:Gather up to 2048 observations holding multiword runs;
:Find standing-bearing claims by observation tier;
:Reject forbidden predicates; sum weighted confidence at opposite endpoints;
:Exclude prompt's own words; print strongest returned pulls;
while (More firmware take steps and no curated fact held back rest?) is (yes)
 switch (Take kind)
 case (fact)
  :Lazily fetch prompt claims; refuse and weigh;
  :Walk witness attestations; choose claim meeting trust threshold;
  if (Qualifying claim found?) then (yes)
   :Print fact; hold back remaining take steps;
  endif
 case (segment)
  :Find every exact prompt occurrence in containing paths;
  :Follow most frequent continuation among surviving trajectories;
  :Stop at end, dominant ending, divergent singletons or 4096 constituents;
  :Apply configured seeded near-top choice; print segment if any;
 case (attestations)
  :Lazily fetch, refuse and weigh prompt claims;
  :take_top; print configured count;
 case (constituents)
  :Fetch claims for unique composed constituents in one set;
  :Apply fan, refusal, weights and take_top per constituent; print;
 case (chain)
  :Rank unique prompt words using attested firmware roles;
  :Try configured relation chains for selected positive-weight words;
  :After first step, also try constituents then original puller;
  :Choose witness-ordered/top claim at each step;
  :Print complete chain answer or point where chain stopped;
 endswitch
endwhile (no)
:Print take count; cleanup; return 0;
stop

start

:database_made; connect; map tier0;
while (More declared extensions?) is (yes)
 :CREATE EXTENSION IF NOT EXISTS;
 if (run reports failure?) then (yes)
  :Return 1;
  stop
 endif
endwhile (no)
:ALTER EXTENSION laplace UPDATE;
:Set database tier0, flags and highway paths;
if (Any checked run fails?) then (yes)
 :Return 1;
 stop
endif
:Find existing public entity / physicality / witness / consensus tables;
:Attempt to adopt tables into extension;
:SELECT laplace_schema_indexes();
if (Index run fails?) then (yes)
 :Return 1;
 stop
endif
:Close and reconnect; enable_parallel_append = on for database;
:Close; return cmd_status result;
stop

start

:Connect;
:SET maintenance_work_mem = 8GB;
if (run succeeds?) then (yes)
 :SELECT laplace_schema_indexes();
 if (run succeeds?) then (yes)
  :ANALYZE;
 endif
endif
:Close; return 0 only if all three checked operations succeeded;
stop

start

:Connect; query extension version, ISA, tier0 path/fingerprint,
database size and server version;
:Print available values with fallback labels;
if (Local tier0 and server fingerprint available?) then (yes)
 :Compare fingerprints; print same or DIFFERS;
endif
:Read and compare highway settings/fingerprints when available;
:Sample entity rows at 1 percent; estimate counts by tier;
:Read planner row estimates and relation sizes;
:Read witness / consensus estimates and index counts;
:Free results and close;
:Return 0;
stop

start

:Connect, map tier0, load recipes and source order;
:Attempt to read witness trunks;
:Collect first constituent of each witness trunk;
while (More configured sources?) is (yes)
 :Count recipes belonging to this source;
 :Decompose source_called name; compare against witness first constituents;
 :Print source order, recipe count, yes/no and discovered root;
 :Print declared after dependencies;
endwhile (no)
:Free map; close; return 0;
stop

start

:Parse roots, connection, tier0, output and verify options;
if (No roots?) then (yes)
 :Return 2;
 stop
endif
:Map tier0; load chess rules;
:Parse root IDs;
if (Invalid root ID?) then (yes)
 :Return 2;
 stop
endif
:Open read connection;
:db_fetch roots and descendants;
:Open output file or use stdout;
if (Output cannot be opened?) then (yes)
 :Return 1;
 stop
endif
while (More roots?) is (yes)
 :records_in; use root itself if present and no records found;
 while (More selected records?) is (yes)
  :record_pgn reconstructs text and accumulates replay statistics;
  :Write reconstructed bytes if nonempty;
 endwhile (no)
endwhile (no)
:Close output file if requested;
if (--verify?) then (yes)
 :verify_ids from constituents / leaves;
endif
:Print replay, Chess960, transposition and verification statistics;
:Close database;
:Return 1 for replay/ID/leaf/dangling/split failures, otherwise 0;
stop

start

:Parse parts, --id, files, voices and TSV;
if (No parts?) then (yes)
 :Return 2;
 stop
endif
:Map tier0; connect;
:Resolve explicit IDs or strands_named;
if (Malformed explicit ID?) then (yes)
 :Return 2;
 stop
endif
:Sort claims by ID;
:Open optional TSV;
if (TSV open fails?) then (yes)
 :Return 1;
 stop
endif
:walk_up from claims through containment;
:Identify parentless trunks and metadata-bearing file nodes;
:roots_known distinguishes witness trunks from other roots;
while (More trunks?) is (yes)
 :rows_under computes claim/voice tallies and optional TSV;
 if (Small claim set?) then (yes)
  :down_from and tally_under; print detailed claim and voice counts;
 endif
endwhile (no)
if (--files?) then (yes)
 :Compute and print per-file rows/tallies;
endif
:Print walk counts and games/tokens; close TSV and database;
:Free DAG, readers, holds and maps; return 0;
stop

start

:Parse layout, file and display-node limit;
if (Layout or file argument absent?) then (yes)
 :Return 2;
 stop
endif
:Open layout;
if (Open fails?) then (yes)
 :Return 1;
 stop
endif
:Read layout lines through layout_says;
if (Layout rejected?) then (yes)
 :Return 2;
 stop
endif
:Open data file;
if (Open fails?) then (yes)
 :Return 1;
 stop
endif
:Read first 1 MiB; trim full-buffer tail to a newline if available;
